import{newSpecPage}from"@stencil/core/testing";import{ScPriceInput}from"../sc-price-input";import{PRICE_INPUT_PATTERN}from"../../../../functions/currency";describe("sc-price-input",(()=>{it("renders",(async()=>{const e=await newSpecPage({components:[ScPriceInput],html:"<sc-price-input></sc-price-input>"});expect(e.root).toMatchSnapshot()})),it("uses the shared price pattern so validation matches the parser",(async()=>{const e=await newSpecPage({components:[ScPriceInput],html:'<sc-price-input currency-code="eur"></sc-price-input>'});expect(e.root.shadowRoot.querySelector("sc-input").getAttribute("pattern")).toBe(PRICE_INPUT_PATTERN)}))}));